"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def FIND_TARGET(rotated_list, target):
    low = 0
    high = (len(rotated_list) - 1)
    while (low <= high):
        mid = ((low + high) // 2)
        if (rotated_list[mid] == target):
            return mid
        elif (rotated_list[low] <= rotated_list[mid]):
            if ((target >= rotated_list[low]) and (target < rotated_list[mid])):
                high = (mid - 1)
            else:
                low = (mid + 1)
        else:
            if ((target > rotated_list[mid]) and (target <= rotated_list[high])):
                low = (mid + 1)
            else:
                high = (mid - 1)
    return (-1)
